import{t as e}from"./api-CVHbzLQj.js";var t={getMyAppointments:async()=>(await e.get(`/appointment/me`)).data,getAppointmentById:async t=>(await e.get(`/appointment/${t}`)).data,getShopAppointments:async t=>(await e.get(`/appointment/shop/${t}`)).data,updateAppointmentStatus:async(t,n)=>n===`CANCELLED`?(await e.patch(`/appointment/${t}/cancel`)).data:(await e.patch(`/appointment/${t}/status`,{status:n})).data,createAppointment:async t=>(await e.post(`/appointment`,t)).data,submitReview:async t=>(await e.post(`/review`,t)).data};export{t};